   422  int blosclz_compress(const int clevel, const void* input, int length,
   423                       void* output, int maxout, const int split_block) {
   424    uint8_t* ibase = (uint8_t*)input;
   425
   426    // Experiments say that checking 1/4 of the buffer is enough to figure out approx cratio
   427    int maxlen = length / 4;
   428    // Start probing somewhere inside the buffer
   429    int shift = length - maxlen;
   430    // Actual entropy probing!
   431    double cratio = get_cratio(ibase + shift, maxlen, 3, 3);
   432    // discard probes with small compression ratios (too expensive)
   433    double cratio_[10] = {0, 2, 1.5, 1.2, 1.2, 1.2, 1.2, 1.15, 1.1, 1.0};
   434    if (cratio < cratio_[clevel]) {
   435      goto out;
   436    }
   437
   438    /* When we go back in a match (shift), we obtain quite different compression properties.
   439     * It looks like 4 is more useful in combination with bitshuffle and small typesizes
   440     * Fallback to 4 because it provides more consistent results for large cratios.
   441     *
   442     * In this block we also check cratios for the beginning of the buffers and
   443     * eventually discard those that are small (take too long to decompress).
   444     * This process is called _entropy probing_.
   445     */
   446    unsigned ipshift = 4;
   447    // Compute optimal shift and minimum lengths for encoding
   448    // Use 4 by default, except for low entropy data, where we should do a best effort
   449    unsigned minlen = 4;
   450    // BloscLZ works better with splits mostly, so when data is not split, do a best effort
   451    // Why using cratio < 4 is based in experiments with low and high entropy
   452    if (!split_block || cratio < 4) {
   453      ipshift = 3;
   454      minlen = 3;
   455    }
   456
   457    uint8_t hashlog_[10] = {0, HASH_LOG - 2, HASH_LOG - 1, HASH_LOG, HASH_LOG,
   458                            HASH_LOG, HASH_LOG, HASH_LOG, HASH_LOG, HASH_LOG};
   459    uint8_t hashlog = hashlog_[clevel];
   460
   461    uint8_t* ip = ibase;
   462    const uint8_t* ip_bound = ibase + length - 1;
   463    const uint8_t* ip_limit = ibase + length - 12;
   464    uint8_t* op = (uint8_t*)output;
   465
   466    /* input and output buffer cannot be less than 16 and 66 bytes or we can get into trouble */
   467    if (length < 16 || maxout < 66) {
   468      return 0;
   469    }
   470
   471    // Initialize the hash table
   472    uint32_t htab[1U << (uint8_t)HASH_LOG];
   473    memset(htab, 0, (1U << hashlog) * sizeof(uint32_t));
   474
   475    /* we start with literal copy */
   476    uint8_t copy = 4;
   477    *op++ = MAX_COPY - 1;
   478    *op++ = *ip++;
   479    *op++ = *ip++;
   480    *op++ = *ip++;
   481    *op++ = *ip++;
   482
   483    /* main loop */
   484    const uint8_t* op_limit = op + maxout;
   485    while (BLOSCLZ_LIKELY(ip < ip_limit)) {
   486      const uint8_t* ref;
   487      unsigned distance;
   488      uint8_t* anchor = ip;    /* comparison starting-point */
   489
   490      /* find potential match */
   491      uint32_t seq = BLOSCLZ_READU32(ip);
   492      uint32_t hval;
   493      HASH_FUNCTION(hval, seq, hashlog)
   494      ref = ibase + htab[hval];
   495
   496      /* calculate distance to the match */
   497      distance = (unsigned int)(anchor - ref);
   498
   499      /* update hash table */
   500      htab[hval] = (uint32_t) (anchor - ibase);
   501
   502      if (distance == 0 || (distance >= MAX_FARDISTANCE)) {
   503        LITERAL(ip, op, op_limit, anchor, copy)
   504        continue;
   505      }
   506
   507      /* is this a match? check the first 4 bytes */
   508      if (BLOSCLZ_UNLIKELY(BLOSCLZ_READU32(ref) == BLOSCLZ_READU32(ip))) {
   509        ref += 4;
   510      } else {
   511        /* no luck, copy as a literal */
   512        LITERAL(ip, op, op_limit, anchor, copy)
   513        continue;
   514      }
   515
   516      /* last matched byte */
   517      ip = anchor + 4;
   518
   519      /* distance is biased */
   520      distance--;
   521
   522      /* get runs or matches; zero distance means a run */
   523      ip = get_run_or_match(ip, ip_bound, ref, !distance);
   524
   525      /* length is biased, '1' means a match of 3 bytes */
   526      ip -= ipshift;
   527
   528      unsigned len = (int)(ip - anchor);
   529
   530      // Encoding short lengths is expensive during decompression
   531      if (len < minlen || (len <= 5 && distance >= MAX_DISTANCE)) {
   532        LITERAL(ip, op, op_limit, anchor, copy)
   533        continue;
   534      }
   535
   536      /* if we have copied something, adjust the copy count */
   537      if (copy)
   538        /* copy is biased, '0' means 1 byte copy */
   539        *(op - copy - 1) = (uint8_t)(copy - 1);
   540      else
   541        /* back, to overwrite the copy count */
   542        op--;
   543      /* reset literal counter */
   544      copy = 0;
   545
   546      /* encode the match */
   547      if (distance < MAX_DISTANCE) {
   548        if (len < 7) {
   549          MATCH_SHORT(op, op_limit, len, distance)
   550        } else {
   551          MATCH_LONG(op, op_limit, len, distance)
   552        }
   553      } else {
   554        /* far away, but not yet in the another galaxy... */
   555        distance -= MAX_DISTANCE;
   556        if (len < 7) {
   557          MATCH_SHORT_FAR(op, op_limit, len, distance)
   558        } else {
   559          MATCH_LONG_FAR(op, op_limit, len, distance)
   560        }
   560      context->decompress_func = &zlib_wrap_decompress;
   561      return 0;
   562    }
   563  #endif /*  HAVE_ZLIB */
   564  #if defined(HAVE_ZSTD)
   565    if (compformat == BLOSC_ZSTD_FORMAT) {
   566      if (compversion != BLOSC_ZSTD_VERSION_FORMAT) {
   567        return -9;
   568      }
   569      context->decompress_func = &zstd_wrap_decompress;
   570      return 0;
   571    }
   572  #endif /*  HAVE_ZSTD */
   573    return -5; /* signals no decompression support */
   574  }
